/* @autogenerated */
package net.civeira.phylax.feature.observe.ingest;

import java.util.Optional;

import io.quarkus.arc.Arc;
import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.observe.source.SourceRegistry.Source;

/**
 * Tells the exporters if the data they receive come from an OTLP request (another origin) or from
 * this process: the own spans are exported from the batch thread, without request context.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class IngestContext {

  private final IngestRequestState state;

  public boolean inRequest() {
    return Arc.container().requestContext().isActive();
  }

  public Optional<Source> keySource() {
    return inRequest() ? state.getSource() : Optional.empty();
  }
}
